const body = { rate: $.input.rateId };
if ($.input.labelFileType && $.input.labelFileType !== 'PDF') body.label_file_type = $.input.labelFileType;
if ($.input.async) body.async = true;
return { body };

const resp = $.steps.createLabel.response || {};
return {
  labelId: resp.object_id || '',
  state: resp.object_state || '',
  trackingNumber: resp.tracking_number || '',
  labelUrl: resp.label_url || '',
  commercialInvoiceUrl: resp.commercial_invoice_url || '',
  eta: resp.eta || '',
  summary: resp.object_id ? `Label ${resp.object_id} created (tracking: ${resp.tracking_number || 'pending'})` : 'Failed to create label'
};
